// School years and terms are generated by the app (never typed in by hand), and a class's
// terms decide whether it is current, future or past on a given date.
export type Term = { id: string; yearId: string; label: string; short: string; start: Date; end: Date; mid: Date };
export type SchoolYear = { id: string; label: string; terms: Term[] };

const d = (y: number, m: number, day: number) => new Date(y, m - 1, day);

/** Academic year containing `date`: Aug 1 starts a new year. */
export const yearStartFor = (date: Date) => (date.getMonth() >= 7 ? date.getFullYear() : date.getFullYear() - 1);

export function makeYear(start: number): SchoolYear {
  const id = String(start);
  const label = `${start}-${String((start + 1) % 100).padStart(2, "0")}`;
  return {
    id, label,
    terms: [
      { id: `${id}-S1`, yearId: id, label: "Semester 1", short: "S1", start: d(start, 8, 25), mid: d(start, 10, 24), end: d(start + 1, 1, 16) },
      { id: `${id}-S2`, yearId: id, label: "Semester 2", short: "S2", start: d(start + 1, 1, 20), mid: d(start + 1, 3, 27), end: d(start + 1, 6, 5) },
    ],
  };
}

/** Last year, this year and next year relative to `date`. */
export const schoolYears = (date: Date = new Date()) => [-1, 0, 1].map((o) => makeYear(yearStartFor(date) + o));
export const termById = (id: string): Term | undefined => makeYear(Number(id.split("-")[0])).terms.find((t) => t.id === id);
export const termLabel = (id: string) => { const t = termById(id); return t ? `${makeYear(Number(t.yearId)).label} ${t.label}` : id; };

export type ClassStatus = "current" | "future" | "past";
/** Current if today falls in one of its terms (or between two of them); future if every term is ahead; otherwise past. */
export function classStatus(termIds: string[], date: Date = new Date()): ClassStatus {
  const ts = termIds.map(termById).filter((t): t is Term => !!t);
  if (!ts.length) return "future";
  const first = Math.min(...ts.map((t) => +t.start)), last = Math.max(...ts.map((t) => +t.end));
  const day = +new Date(date.getFullYear(), date.getMonth(), date.getDate());
  if (day < first) return "future";
  if (day > last) return "past";
  return "current";
}
/** The class term a date falls in, if any (attendance and grading only happen inside a class term). */
export const termOn = (termIds: string[], date: Date) =>
  termIds.map(termById).find((t) => t && +date >= +t.start && +date <= +t.end + 86399999);

/** Grading periods for a class: a mid-term progress report and the final grade for each of its terms. */
export const gradingPeriods = (termIds: string[]) =>
  termIds.map(termById).filter((t): t is Term => !!t).flatMap((t) => [
    { id: `${t.id}-M`, label: `Mid-${t.label}` }, { id: t.id, label: t.label },
  ]);
